practice.solution:
#include <iostream>

bool printQuotient(int value, int divisor)
{
    if (divisor == 0) return false;
    std::cout << value / divisor;
    return true;
}

int main()
{
    if (!printQuotient(12, 0)) std::cout << "No quotient\n";
    return 0;
}

practice.tests:
#define main learner_main
#include "main.cpp"
#undef main
#include <sstream>
#include <string>

int main()
{
    struct Case { int value; int divisor; bool success; const char* output; };
    const Case cases[]{{12, 3, true, "4"}, {7, 2, true, "3"}, {-7, 2, true, "-3"}, {7, -2, true, "-3"}, {-7, -2, true, "3"}, {0, 4, true, "0"}, {12, 0, false, ""}, {0, 0, false, ""}};
    int failures{};
    for (const auto& c : cases)
    {
        std::ostringstream captured;
        auto* old{std::cout.rdbuf(captured.rdbuf())};
        const bool actual{printQuotient(c.value, c.divisor)};
        std::cout.rdbuf(old);
        if (actual != c.success || captured.str() != c.output)
        {
            std::cerr << "Wrong flag or output for " << c.value << ", " << c.divisor << '\n';
            ++failures;
        }
    }
    return failures == 0 ? 0 : 1;
}

